/* bcopy - Berklix equivalent of memcpy *//* NOTE THE ARGUMENT ORDER.  bcopy takes (source, destination, length);   memcpy takes (destination, source, length).  They are the reverse of   each other, and getting it wrong is silent. */void bcopy(src, dst, length)          char *src;          char *dst;          int length;          {          (void) memcpy(dst, src, length);          } /* end of bcopy */